insert into public.resources (title, description, category, url, tags, uploaded_by, created_at) values
  ('MIT Sloan — the full course catalogue on OCW', 'Every Sloan course MIT has published: accounting, operations, system dynamics, organisational processes, entrepreneurship. Free lecture notes for anything you''re behind on.', 'Core Curriculum', 'https://ocw.mit.edu/search/?d=Sloan%20School%20of%20Management', ARRAY['academics', 'MIT', 'lecture notes']::text[], NULL, '2026-07-12T00:00:00.000Z'),
  ('NPTEL — Indian management course library', 'IIT and IISc video courses in management, operations research and economics. Useful when you want the same topic explained a second way, in an Indian context.', 'Core Curriculum', 'https://nptel.ac.in/courses', ARRAY['academics', 'India', 'lectures']::text[], NULL, '2026-07-13T00:00:00.000Z'),
  ('Wharton Business Foundations (Coursera)', 'Wharton''s core MBA sequence — accounting, marketing, operations, finance — auditable free. The fastest way to fill a weak spot in the core.', 'Core Curriculum', 'https://www.coursera.org/specializations/wharton-business-foundations', ARRAY['core', 'Wharton', 'courses']::text[], NULL, '2026-07-14T00:00:00.000Z'),
  ('Corporate Finance Institute — free course collection', 'CFI''s free tier covers accounting fundamentals, Excel and an introduction to valuation. Certificates are optional; the templates are the real value.', 'Core Curriculum', 'https://corporatefinanceinstitute.com/collections/', ARRAY['templates', 'finance', 'Excel']::text[], NULL, '2026-07-15T00:00:00.000Z'),
  ('ISB — faculty research and thought leadership', 'What our own faculty publish, by area. Worth a scan before you pick electives or approach a professor about a project.', 'Core Curriculum', 'https://www.isb.edu/faculty-and-research', ARRAY['ISB', 'research', 'faculty']::text[], NULL, '2026-07-16T00:00:00.000Z'),
  ('MIT OCW 15.501 — Financial and Managerial Accounting', 'The full MIT accounting core: lecture notes, problem sets and solutions. Covers accrual accounting, the three statements and how they link.', 'Financial Accounting', 'https://ocw.mit.edu/courses/15-501-introduction-to-financial-and-managerial-accounting-spring-2004/', ARRAY['accounting', 'MIT', 'core']::text[], NULL, '2026-07-17T00:00:00.000Z'),
  ('AccountingCoach', 'Plain-English explanations of every accounting concept, with practice quizzes. The place to go when a debit/credit still doesn''t feel obvious.', 'Financial Accounting', 'https://www.accountingcoach.com/', ARRAY['accounting', 'basics', 'practice']::text[], NULL, '2026-07-18T00:00:00.000Z'),
  ('Investopedia financial dictionary', 'When a term shows up in a case and you have ninety seconds to understand it before you speak.', 'Financial Accounting', 'https://www.investopedia.com/financial-term-dictionary-4769738', ARRAY['glossary', 'basics']::text[], NULL, '2026-07-19T00:00:00.000Z'),
  ('Damodaran Online — the full valuation course', 'Aswath Damodaran''s entire NYU Stern class: slides, lecture videos, spreadsheets and the industry datasets he updates every January. If you bookmark one finance site, this is it.', 'Corporate Finance', 'https://pages.stern.nyu.edu/~adamodar/', ARRAY['valuation', 'NYU Stern', 'core']::text[], NULL, '2026-07-20T00:00:00.000Z'),
  ('Damodaran''s updated industry datasets', 'Betas, cost of capital, margins and multiples by sector and geography — the numbers you cite when a professor asks where your WACC came from.', 'Corporate Finance', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/data.html', ARRAY['data', 'WACC', 'valuation']::text[], NULL, '2026-07-21T00:00:00.000Z'),
  ('MIT OCW 15.401 — Finance Theory I', 'Full lecture notes and problem sets covering NPV, portfolio theory, CAPM and capital structure. Maps almost one-to-one onto the corporate finance core.', 'Corporate Finance', 'https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/', ARRAY['corporate finance', 'MIT', 'core']::text[], NULL, '2026-07-22T00:00:00.000Z'),
  ('Musings on Markets — Damodaran''s blog', 'He values live situations as they happen: IPOs, takeovers, market panics. The best demonstration anywhere of finance theory meeting a real number.', 'Corporate Finance', 'https://aswathdamodaran.blogspot.com/', ARRAY['valuation', 'markets', 'writing']::text[], NULL, '2026-07-23T00:00:00.000Z'),
  ('Macabacus — modelling and Excel best practice', 'How bankers actually structure and format models: circularity, toggles, and the keyboard shortcuts that pay for themselves in week one.', 'Corporate Finance', 'https://macabacus.com/learn', ARRAY['Excel', 'modelling', 'formatting']::text[], NULL, '2026-07-24T00:00:00.000Z'),
  ('A Simple Model — free financial modelling course', 'Builds a three-statement model from a blank sheet across short videos, with downloadable Excel files at every stage.', 'Corporate Finance', 'https://www.asimplemodel.com/', ARRAY['modelling', 'Excel', 'three-statement']::text[], NULL, '2026-07-25T00:00:00.000Z'),
  ('Aswath Damodaran on YouTube', 'Full valuation and corporate finance lectures, plus running commentary on live deals. Watch at 1.5x.', 'Corporate Finance', 'https://www.youtube.com/@AswathDamodaranonValuation', ARRAY['valuation', 'lectures', 'video']::text[], NULL, '2026-07-26T00:00:00.000Z'),
  ('MIT OCW 14.01 — Principles of Microeconomics', 'Jonathan Gruber''s course with video lectures, problem sets and past exams. Supply and demand through to externalities and welfare.', 'Managerial Economics', 'https://ocw.mit.edu/courses/14-01-principles-of-microeconomics-fall-2023/', ARRAY['microeconomics', 'MIT', 'core']::text[], NULL, '2026-07-27T00:00:00.000Z'),
  ('Marginal Revolution University', 'Short, sharp economics videos from Tyler Cowen and Alex Tabarrok. Best free explanation of pricing power, incentives and trade.', 'Managerial Economics', 'https://mru.org/', ARRAY['economics', 'video', 'pricing']::text[], NULL, '2026-07-28T00:00:00.000Z'),
  ('MIT OCW 15.810 — Marketing Management', 'Segmentation, positioning, pricing and channel strategy, with the case list and analytics assignments. Good companion reading before marketing sessions.', 'Marketing', 'https://ocw.mit.edu/courses/15-810-marketing-management-analytics-frameworks-and-applications-fall-2015/', ARRAY['marketing', 'MIT', 'core']::text[], NULL, '2026-07-29T00:00:00.000Z'),
  ('Seth Godin''s blog', 'A decade of short posts on positioning and permission marketing. Read ten at random; at least three will change how you write.', 'Marketing', 'https://seths.blog/', ARRAY['positioning', 'writing', 'brand']::text[], NULL, '2026-07-30T00:00:00.000Z'),
  ('Reforge blog — growth frameworks', 'Retention, growth loops and monetisation frameworks written by operators. Strong for anyone recruiting into growth or D2C.', 'Marketing', 'https://www.reforge.com/blog', ARRAY['growth', 'retention', 'loops']::text[], NULL, '2026-07-31T00:00:00.000Z'),
  ('MIT OCW 15.761 — Introduction to Operations Management', 'Process analysis, inventory, queueing and the bullwhip effect, with the problem sets. The operations core in one page.', 'Operations & Supply Chain', 'https://ocw.mit.edu/courses/15-761-introduction-to-operations-management-spring-2013/', ARRAY['operations', 'MIT', 'core']::text[], NULL, '2026-08-01T00:00:00.000Z'),
  ('MITx supply chain courses on edX', 'MIT CTL''s supply chain analytics and fundamentals courses — audit free. The best structured operations content online.', 'Operations & Supply Chain', 'https://www.edx.org/school/mitx', ARRAY['supply chain', 'analytics', 'courses']::text[], NULL, '2026-08-02T00:00:00.000Z'),
  ('Porter — The Five Competitive Forces (HBR)', 'The original article, not the textbook summary. Twenty minutes, and it reframes every industry-attractiveness question you''ll be asked.', 'Strategy', 'https://hbr.org/2008/01/the-five-competitive-forces-that-shape-strategy', ARRAY['frameworks', 'HBR', 'industry']::text[], NULL, '2026-08-03T00:00:00.000Z'),
  ('HBS Working Knowledge', 'Harvard Business School''s research digest — short, readable write-ups of new faculty research across strategy, finance and organisations.', 'Strategy', 'https://www.library.hbs.edu/working-knowledge', ARRAY['research', 'HBS']::text[], NULL, '2026-08-04T00:00:00.000Z'),
  ('Stratechery archive', 'Ben Thompson on platform strategy and aggregation theory. The clearest writing anywhere on why technology businesses win.', 'Strategy', 'https://stratechery.com/', ARRAY['tech strategy', 'platforms', 'writing']::text[], NULL, '2026-08-05T00:00:00.000Z'),
  ('McKinsey — Featured Insights', 'Free industry reports and the McKinsey Quarterly archive. Two of these on your target sector before an interview is a cheat code.', 'Strategy', 'https://www.mckinsey.com/featured-insights', ARRAY['research', 'industry', 'MBB']::text[], NULL, '2026-08-06T00:00:00.000Z'),
  ('BCG Publications', 'BCG''s public research library, strongest on climate, technology adoption and consumer sentiment surveys.', 'Strategy', 'https://www.bcg.com/publications', ARRAY['research', 'industry', 'MBB']::text[], NULL, '2026-08-07T00:00:00.000Z'),
  ('Bain Insights', 'Bain''s reports, including the annual Global Private Equity Report and the India consumer studies.', 'Strategy', 'https://www.bain.com/insights/', ARRAY['research', 'PE', 'consumer']::text[], NULL, '2026-08-08T00:00:00.000Z'),
  ('HBR — Leadership', 'HBR''s leadership archive: feedback, managing up, running teams, and the transition from doing the work to leading it.', 'Leadership & People', 'https://hbr.org/topic/subject/leadership', ARRAY['leadership', 'management', 'HBR']::text[], NULL, '2026-08-09T00:00:00.000Z'),
  ('Harvard Program on Negotiation', 'Daily articles from the people who wrote Getting to Yes. Negotiation is the one core skill that pays off in salary talks the same week you learn it.', 'Leadership & People', 'https://www.pon.harvard.edu/', ARRAY['negotiation', 'Harvard', 'influence']::text[], NULL, '2026-08-10T00:00:00.000Z'),
  ('HBR — Negotiation strategies', 'Case-based pieces on anchoring, BATNA and multi-party deals. Pairs well with the PON material above.', 'Leadership & People', 'https://hbr.org/topic/subject/negotiation-strategies', ARRAY['negotiation', 'HBR']::text[], NULL, '2026-08-11T00:00:00.000Z'),
  ('Radical Candor', 'Kim Scott''s framework for feedback that is neither brutal nor useless. Immediately applicable to study groups, not just teams you manage later.', 'Leadership & People', 'https://www.radicalcandor.com/', ARRAY['feedback', 'management', 'teams']::text[], NULL, '2026-08-12T00:00:00.000Z'),
  ('Farnam Street', 'Mental models and decision-making, well written and free. Good antidote to framework-shaped thinking.', 'Leadership & People', 'https://fs.blog/', ARRAY['decisions', 'mental models', 'writing']::text[], NULL, '2026-08-13T00:00:00.000Z'),
  ('MIT OCW 15.075 — Statistical Thinking and Data Analysis', 'The statistics core done properly: hypothesis testing, regression and design of experiments, with problem sets and solutions.', 'Analytics & Decision Sciences', 'https://ocw.mit.edu/courses/15-075j-statistical-thinking-and-data-analysis-fall-2011/', ARRAY['statistics', 'regression', 'MIT']::text[], NULL, '2026-08-14T00:00:00.000Z'),
  ('StatQuest with Josh Starmer', 'If regression output still feels like magic, this fixes it. Every concept explained visually in under fifteen minutes.', 'Analytics & Decision Sciences', 'https://www.youtube.com/@statquest', ARRAY['statistics', 'video', 'basics']::text[], NULL, '2026-08-15T00:00:00.000Z'),
  ('Khan Academy — Statistics and Probability', 'The refresher to run before the quant methods midterm. Free, structured, with practice problems.', 'Analytics & Decision Sciences', 'https://www.khanacademy.org/math/statistics-probability', ARRAY['statistics', 'basics', 'practice']::text[], NULL, '2026-08-16T00:00:00.000Z'),
  ('The SQL Tutorial (ThoughtSpot, formerly Mode)', 'From SELECT to window functions in a live query editor on real datasets. Two evenings gets you interview-ready SQL.', 'Analytics & Decision Sciences', 'https://www.thoughtspot.com/sql-tutorial', ARRAY['SQL', 'data', 'hands-on']::text[], NULL, '2026-08-17T00:00:00.000Z'),
  ('Kaggle Learn — micro-courses', 'Two-hour hands-on courses in pandas, data visualisation and intro ML. Practical, no maths gatekeeping.', 'Analytics & Decision Sciences', 'https://www.kaggle.com/learn', ARRAY['pandas', 'data', 'ML']::text[], NULL, '2026-08-18T00:00:00.000Z'),
  ('Google Data Analytics Professional Certificate', 'The most cited analytics certificate on Indian CVs. Long, but genuinely covers spreadsheets, SQL, R and dashboards.', 'Analytics & Decision Sciences', 'https://www.coursera.org/professional-certificates/google-data-analytics', ARRAY['certificate', 'analytics', 'courses']::text[], NULL, '2026-08-19T00:00:00.000Z'),
  ('ExcelJet — formulas and shortcuts', 'Every function explained in one screen with a worked example. The fastest Excel reference on the internet.', 'Analytics & Decision Sciences', 'https://exceljet.net/', ARRAY['Excel', 'formulas', 'productivity']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('Harvard CS50x', 'Still the best introduction to computer science. Take it if you want to genuinely understand what your engineers do. Free.', 'Technology & AI', 'https://cs50.harvard.edu/x/', ARRAY['CS', 'programming', 'courses']::text[], NULL, '2026-07-24T00:00:00.000Z'),
  ('Practical Deep Learning for Coders (fast.ai)', 'Top-down, code-first deep learning. You build a working model in lesson one and learn the theory afterwards.', 'Technology & AI', 'https://course.fast.ai/', ARRAY['AI', 'deep learning', 'courses']::text[], NULL, '2026-07-25T00:00:00.000Z'),
  ('Neural Networks: Zero to Hero — Karpathy', 'Builds a language model from scratch, line by line. The clearest explanation of how LLMs actually work.', 'Technology & AI', 'https://karpathy.ai/zero-to-hero.html', ARRAY['AI', 'LLM', 'video']::text[], NULL, '2026-07-26T00:00:00.000Z'),
  ('DeepLearning.AI courses', 'Short, free courses on RAG, agents, evaluation and prompting — built with the labs shipping the tools.', 'Technology & AI', 'https://www.deeplearning.ai/courses', ARRAY['AI', 'LLM', 'courses']::text[], NULL, '2026-07-27T00:00:00.000Z'),
  ('Claude — prompt engineering guide', 'The practical documentation on getting reliable output from an LLM. Immediately useful for research, summarisation and analysis work.', 'Technology & AI', 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', ARRAY['AI', 'prompting', 'productivity']::text[], NULL, '2026-07-28T00:00:00.000Z'),
  ('Y Combinator Startup School', 'Free, structured curriculum on going from idea to launch, with the library of YC founder talks attached.', 'Entrepreneurship & VC', 'https://www.startupschool.org/', ARRAY['startups', 'founders', 'YC']::text[], NULL, '2026-07-29T00:00:00.000Z'),
  ('Paul Graham''s essays', 'Twenty years of writing on startups, ideas and doing ambitious work. Start with ''Do Things That Don''t Scale''.', 'Entrepreneurship & VC', 'https://paulgraham.com/articles.html', ARRAY['startups', 'essays']::text[], NULL, '2026-07-30T00:00:00.000Z'),
  ('Sequoia — writing a business plan', 'The pitch deck outline most Indian seed investors still expect, straight from the source.', 'Entrepreneurship & VC', 'https://sequoiacap.com/article/writing-a-business-plan', ARRAY['fundraising', 'pitch deck', 'VC']::text[], NULL, '2026-07-31T00:00:00.000Z'),
  ('First Round Review', 'Long-form operator interviews on hiring, pricing and scaling. The closest thing to a free operating manual.', 'Entrepreneurship & VC', 'https://review.firstround.com/', ARRAY['operations', 'hiring', 'startups']::text[], NULL, '2026-08-01T00:00:00.000Z'),
  ('a16z — insights and podcasts', 'Sector theses on AI, fintech and consumer. Useful for framing why a market is interesting in a VC interview.', 'Entrepreneurship & VC', 'https://a16z.com/', ARRAY['VC', 'theses', 'tech']::text[], NULL, '2026-08-02T00:00:00.000Z'),
  ('Inc42 — Indian startup ecosystem', 'Funding news, sector reports and DataLabs research on Indian startups.', 'Entrepreneurship & VC', 'https://inc42.com/', ARRAY['India', 'startups', 'funding']::text[], NULL, '2026-08-03T00:00:00.000Z'),
  ('Zerodha Varsity', 'The best free Indian markets curriculum: equities, futures, options, and a genuinely good module on reading annual reports.', 'Investments & Markets', 'https://zerodha.com/varsity/', ARRAY['India', 'markets', 'equities']::text[], NULL, '2026-08-04T00:00:00.000Z'),
  ('CFA Program — curriculum overview', 'What the charter actually covers and what it costs in hours. Worth reading before you commit to Level I alongside term exams.', 'Investments & Markets', 'https://www.cfainstitute.org/programs/cfa-program', ARRAY['CFA', 'certification', 'investing']::text[], NULL, '2026-08-05T00:00:00.000Z'),
  ('Finshots — three-minute business news', 'Daily Indian business explainers. The cheapest way to sound informed in a networking call.', 'Investments & Markets', 'https://finshots.in/', ARRAY['India', 'news', 'business']::text[], NULL, '2026-08-06T00:00:00.000Z'),
  ('The Ken', 'Long-form Indian business journalism. One properly reported story a day — good for industry prep on Indian firms.', 'Investments & Markets', 'https://the-ken.com/', ARRAY['India', 'journalism', 'industry']::text[], NULL, '2026-08-07T00:00:00.000Z'),
  ('PrepLounge case library', '220+ practice cases from coaches and partner firms, with a partner-matching tool so you always have someone to practise with.', 'Consulting Prep', 'https://www.preplounge.com/en/management-consulting-cases', ARRAY['cases', 'practice', 'partners']::text[], NULL, '2026-08-08T00:00:00.000Z'),
  ('McKinsey — official interview prep', 'How the firm describes its own process, plus the Solve assessment and sample cases. Read this before any mock.', 'Consulting Prep', 'https://www.mckinsey.com/careers/interviewing', ARRAY['MBB', 'interviews', 'Solve']::text[], NULL, '2026-08-09T00:00:00.000Z'),
  ('BCG — case interview preparation', 'BCG''s interactive case library and guided practice cases, including the chatbot case.', 'Consulting Prep', 'https://careers.bcg.com/global/en/case-interview-preparation', ARRAY['MBB', 'interviews', 'cases']::text[], NULL, '2026-08-10T00:00:00.000Z'),
  ('Bain — case interview preparation', 'Bain''s practice cases with written walkthroughs, including the coffee shop and FashionCo. classics.', 'Consulting Prep', 'https://www.bain.com/careers/hiring-process/case-interview/', ARRAY['MBB', 'interviews', 'cases']::text[], NULL, '2026-08-11T00:00:00.000Z'),
  ('Victor Cheng — Case Interview Secrets', 'The classic structure resource. Skim the free videos, steal the issue-tree habit, and drop the rigid frameworks.', 'Consulting Prep', 'https://caseinterview.com/', ARRAY['cases', 'frameworks', 'structure']::text[], NULL, '2026-08-12T00:00:00.000Z'),
  ('RocketBlocks — consulting drills', 'Drill-based prep: market sizing, chart reading, mental maths. Fifteen minutes a day beats one panicked weekend.', 'Consulting Prep', 'https://www.rocketblocks.me/', ARRAY['drills', 'market sizing', 'practice']::text[], NULL, '2026-08-13T00:00:00.000Z'),
  ('think-cell — video tutorials', 'How consultants build waterfall, Marimekko and Gantt charts fast. Even without the licence, the chart grammar is worth learning.', 'Consulting Prep', 'https://www.think-cell.com/en/resources/videos', ARRAY['decks', 'charts', 'PowerPoint']::text[], NULL, '2026-08-14T00:00:00.000Z'),
  ('Wall Street Prep — free resources', 'Hundreds of short explainers on accounting, LBO mechanics, comps and precedent transactions. The de facto glossary for finance recruiting.', 'Finance Prep', 'https://www.wallstreetprep.com/free-resources/', ARRAY['IB', 'modelling', 'technicals']::text[], NULL, '2026-08-15T00:00:00.000Z'),
  ('Mergers & Inquisitions', 'Brutally honest guides to IB, PE and hedge fund recruiting: what the job is, what the interview asks, and what the exit actually looks like.', 'Finance Prep', 'https://mergersandinquisitions.com/', ARRAY['IB', 'recruiting', 'careers']::text[], NULL, '2026-08-16T00:00:00.000Z'),
  ('Wall Street Oasis', 'The forums, company reviews and interview question banks. Read it for the question archive, not the tone.', 'Finance Prep', 'https://www.wallstreetoasis.com/', ARRAY['IB', 'interviews', 'forums']::text[], NULL, '2026-08-17T00:00:00.000Z'),
  ('Lenny''s Newsletter', 'The default reading for product people: growth, PM career paths, and hiring loops at real companies.', 'Product Management', 'https://www.lennysnewsletter.com/', ARRAY['product', 'growth', 'careers']::text[], NULL, '2026-08-18T00:00:00.000Z'),
  ('SVPG — Marty Cagan''s articles', 'Product discovery, empowered teams, and why feature factories fail. Read ''Product vs Feature Teams'' first.', 'Product Management', 'https://www.svpg.com/articles/', ARRAY['product', 'discovery', 'teams']::text[], NULL, '2026-08-19T00:00:00.000Z'),
  ('Exponent — PM interview course', 'Product sense, execution, analytics and behavioural rounds, with recorded mocks from people who got the offer.', 'Product Management', 'https://www.tryexponent.com/courses/pm', ARRAY['interviews', 'mocks', 'product']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('Cracking the PM Interview — companion site', 'Gayle McDowell and Jackie Bavaro''s material: role definitions, estimation, and the answer structures that work.', 'Product Management', 'https://www.crackingthepminterview.com/', ARRAY['interviews', 'product', 'books']::text[], NULL, '2026-08-21T00:00:00.000Z'),
  ('Levels.fyi — compensation data', 'Real, verified pay bands by company, level and city. Use it before you negotiate anything.', 'Careers & Networking', 'https://www.levels.fyi/', ARRAY['compensation', 'negotiation']::text[], NULL, '2026-08-22T00:00:00.000Z'),
  ('Ask a Manager', 'Twenty years of workplace questions answered well. Unreasonably useful for internships and first-job politics.', 'Careers & Networking', 'https://www.askamanager.org/', ARRAY['workplace', 'advice']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('Harvard Business Publishing Education', 'Where most of the cases we''re assigned come from. Student pricing, and the free preview pages are often enough for context.', 'Case Studies', 'https://hbsp.harvard.edu/home/', ARRAY['HBS', 'cases', 'academics']::text[], NULL, '2026-08-21T00:00:00.000Z'),
  ('The Case Centre', 'The world''s largest case collection — search by company or topic when you want extra practice on an industry you don''t know.', 'Case Studies', 'https://www.thecasecentre.org/', ARRAY['cases', 'research']::text[], NULL, '2026-08-22T00:00:00.000Z'),
  ('Ivey Publishing', 'The other major case publisher, with much stronger coverage of Indian and emerging-market companies than HBP.', 'Case Studies', 'https://www.iveypublishing.ca/s/', ARRAY['cases', 'India', 'emerging markets']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('The Personal MBA — reading list', 'Josh Kaufman''s list of the business books actually worth the hours, ranked and summarised.', 'Books', 'https://personalmba.com/best-business-books/', ARRAY['reading list']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('Thinking, Fast and Slow', 'Kahneman on judgement under uncertainty. Shows up in behavioural finance, marketing and negotiation alike.', 'Books', 'https://www.goodreads.com/book/show/11468377-thinking-fast-and-slow', ARRAY['behavioural', 'decisions']::text[], NULL, '2026-08-24T00:00:00.000Z'),
  ('The Goal — Goldratt', 'A novel about a factory that teaches the theory of constraints better than any operations textbook. Read it before the operations core.', 'Books', 'https://www.goodreads.com/book/show/113934.The_Goal', ARRAY['operations', 'constraints']::text[], NULL, '2026-08-24T00:00:00.000Z'),
  ('Competitive Strategy — Porter', 'The source text behind half the strategy syllabus. Skim the first four chapters and you''ll follow every session.', 'Books', 'https://www.goodreads.com/book/show/40646.Competitive_Strategy', ARRAY['strategy', 'Porter']::text[], NULL, '2026-08-24T00:00:00.000Z'),
  ('Good Strategy Bad Strategy — Rumelt', 'The best book on why most ''strategy'' documents are goals with adjectives. Useful the week before any strategy submission.', 'Books', 'https://www.goodreads.com/book/show/11721966-good-strategy-bad-strategy', ARRAY['strategy', 'diagnosis']::text[], NULL, '2026-08-25T00:00:00.000Z'),
  ('A Random Walk Down Wall Street', 'Malkiel on markets, indexing and why most active management underperforms. The counterweight to a term of stock pitches.', 'Books', 'https://www.goodreads.com/book/show/900892.A_Random_Walk_Down_Wall_Street', ARRAY['investing', 'markets']::text[], NULL, '2026-08-25T00:00:00.000Z'),
  ('Zero to One — Thiel', 'Contrarian, arguable and short. Useful as a foil in any entrepreneurship discussion.', 'Books', 'https://www.goodreads.com/book/show/18050143-zero-to-one', ARRAY['startups', 'strategy']::text[], NULL, '2026-08-25T00:00:00.000Z');
insert into public.opportunities (title, company, type, industry, role, location, deadline, description, url, posted_by, status, created_at) values
insert into public.help_requests (title, description, tags, posted_by, status, created_at) values
